 "content": "from collections import Counter


def _period(grid):
    rows, cols = len(grid), len(grid[0])
    best_p, best_err = 1, float('inf')
    # The patterned field uses a short horizontal cycle; choose the smallest
    # period that explains the visible cells across all patterned rows.
    for p in range(2, min(12, cols - 3) + 1):
        total = errors = 0
        for r in range(3, rows):
            groups = {}
            for c in range(3, cols):
                v = grid[r][c]
                if v:
                    groups.setdefault(c % p, []).append(v)
            for vals in groups.values():
                total += len(vals)
                errors += len(vals) - Counter(vals).most_common(1)[0][1]
        rate = errors / total if total else 1
        if rate < best_err - 1e-12:
            best_p, best_err = p, rate
    return best_p


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    p = _period(grid)
    for r in range(h):
        # The outer field is a fixed background with a color-4 frame.
        for c in range(min(3, w)):
            if out[r][c] == 0:
                out[r][c] = 1 if c < 2 or r < 2 else 4
        if r < 2:
            for c in range(3, w):
                if out[r][c] == 0:
                    out[r][c] = 1
        elif r == 2:
            for c in range(3, w):
                if out[r][c] == 0:
                    out[r][c] = 4
        else:
            groups = {}
            for c in range(3, w):
                v = grid[r][c]
                if v:
                    groups.setdefault(c % p, []).append(v)
            modes = {k: Counter(vs).most_common(1)[0][0] for k, vs in groups.items()}
            for c in range(3, w):
                if out[r][c] == 0:
                    vals = groups.get(c % p)
                    if vals:
                        out[r][c] = Counter(vals).most_common(1)[0][0]
    return out
